// Check Health — new failed runs since the last check, watched workflows that got switched off, and a morning digest.
const cfg = $('Config').first().json;
// ---- shared helpers ----
const MIN = 60000;
const nowMs = () => (cfg.now_override ? Date.parse(cfg.now_override) : Date.now());
const digitsOf = (value) => String(value || '').replace(/[^\d]/g, '');
// Phones are stored in one international form, so the same person is recognised however they typed it.
function phoneOf(value) {
  const rules = cfg.phone || {};
  let d = digitsOf(value);
  if (d.startsWith('00')) d = d.slice(2);
  else if (rules.national_prefix && rules.country_code && d.startsWith(rules.national_prefix) && !d.startsWith(rules.country_code)) {
    d = rules.country_code + d.slice(rules.national_prefix.length);
  }
  return d.length >= 9 && d.length <= 15 ? '+' + d : '';
}
function emailOf(value) {
  const e = String(value || '').trim().toLowerCase();
  return /^[^\s@<>()",;]+@[^\s@<>()",;]+\.[a-z]{2,}$/.test(e) ? e : '';
}
const localText = (ms) => new Intl.DateTimeFormat(cfg.locale || 'ru-RU', {
  timeZone: cfg.timezone, day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit',
}).format(new Date(ms));
function localParts(ms) {
  const parts = {};
  for (const p of new Intl.DateTimeFormat('en-GB', { timeZone: cfg.timezone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', weekday: 'short' }).formatToParts(new Date(ms))) parts[p.type] = p.value;
  return { date: `${parts.year}-${parts.month}-${parts.day}`, hour: Number(parts.hour), minute: Number(parts.minute), weekday: parts.weekday.toLowerCase().slice(0, 3) };
}
const sheetUrl = (path) => `${cfg.sheets_api_base}/spreadsheets/${encodeURIComponent(cfg.spreadsheet_id)}/values/${path}`;
const quoteSheet = (name) => "'" + String(name).replace(/'/g, "''") + "'";
const plural = (n, one, few, many) => (n % 10 === 1 && n % 100 !== 11 ? one : n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 10 || n % 100 >= 20) ? few : many);
const pad = (n) => String(n).padStart(2, '0');
const stamp = (ms) => { const p = localParts(ms); return `${p.date} ${pad(p.hour)}:${pad(p.minute)}`; };
const now = nowMs();
const state = $getWorkflowStaticData('global');
const workflows = ($('Read Workflows').first().json.data || []);
const executions = ($input.first().json.data || []);
const names = Object.fromEntries(workflows.map((w) => [String(w.id), w.name]));
const ignore = new Set((cfg.ignore_workflow_ids || []).map(String));
const watchAll = !(cfg.watch_workflow_ids || []).length;
const watched = (id) => !ignore.has(String(id)) && (watchAll || (cfg.watch_workflow_ids || []).map(String).includes(String(id)));
const ui = String(cfg.n8n_url || '').replace(/\/$/, '');
const link = (wf, ex) => (ui ? `${ui}/workflow/${wf}/executions/${ex}` : `запуск ${ex}`);
const at = (e) => Date.parse(e.stoppedAt || e.startedAt || '') || 0;
const since = Number(state.last_check) || now - (cfg.check_every_minutes || 60) * MIN;
const out = [];

// New failures, grouped by workflow so a broken workflow is one message, not fifty.
const fresh = executions.filter((e) => watched(e.workflowId) && at(e) > since && at(e) <= now);
if (fresh.length) {
  const by = {};
  for (const e of fresh) (by[e.workflowId] = by[e.workflowId] || []).push(e);
  const lines = Object.entries(by).sort((a, b) => b[1].length - a[1].length).map(([wf, list]) => {
    const last = list.reduce((x, y) => (at(y) > at(x) ? y : x));
    return `• ${names[wf] || 'воркфлоу ' + wf} — ${list.length} ${plural(list.length, 'ошибка', 'ошибки', 'ошибок')}, последняя ${stamp(at(last))}\n  ${link(wf, last.id)}`;
  });
  out.push({ send: true, kind: 'errors', text: [`${cfg.client_name ? cfg.client_name + ': ' : ''}ошибки в n8n с ${stamp(since)}`, ...lines].join('\n') });
}

// Workflows that must run but are switched off (by a person or by n8n after trigger errors).
const must = (cfg.must_be_active || []).map(String);
const alerted = new Set(state.inactive || []);
const off = workflows.filter((w) => must.includes(String(w.id)) && !w.active);
const missing = must.filter((id) => !names[id]);
const newlyOff = off.filter((w) => !alerted.has(String(w.id)));
const backOn = [...alerted].filter((id) => !off.some((w) => String(w.id) === id) && names[id]);
if (newlyOff.length || missing.some((id) => !alerted.has(id))) {
  out.push({ send: true, kind: 'inactive', text: [`${cfg.client_name ? cfg.client_name + ': ' : ''}выключены воркфлоу, которые должны работать`,
    ...newlyOff.map((w) => `• ${w.name}${ui ? '\n  ' + ui + '/workflow/' + w.id : ''}`), ...missing.filter((id) => !alerted.has(id)).map((id) => `• воркфлоу ${id} не найден — удалён?`)].join('\n') });
}
if (backOn.length) out.push({ send: true, kind: 'back', text: `Снова работают: ${backOn.map((id) => names[id]).join(', ')}` });
state.inactive = [...off.map((w) => String(w.id)), ...missing];

// Morning digest, once a day.
const p = localParts(now);
if (p.hour === (cfg.digest_hour === undefined ? 9 : cfg.digest_hour) && state.digest_date !== p.date) {
  const day = executions.filter((e) => watched(e.workflowId) && at(e) > now - 24 * 60 * MIN);
  const by = {};
  for (const e of day) by[e.workflowId] = (by[e.workflowId] || 0) + 1;
  const active = workflows.filter((w) => w.active && watched(w.id));
  out.push({ send: true, kind: 'digest', text: [
    `${cfg.client_name ? cfg.client_name + ' · ' : ''}n8n за сутки`,
    `Активных воркфлоу: ${active.length}`,
    day.length ? `Ошибок: ${day.length}` : 'Ошибок нет ✅',
    ...Object.entries(by).sort((a, b) => b[1] - a[1]).slice(0, 10).map(([wf, n]) => `• ${names[wf] || wf}: ${n}`),
    off.length ? `Выключены: ${off.map((w) => w.name).join(', ')}` : '',
  ].filter(Boolean).join('\n') });
  state.digest_date = p.date;
}
state.last_check = now;
return out.length ? out.map((json) => ({ json: Object.assign({ chat: cfg.alert_chat_id }, json) })) : [{ json: { send: false } }];
